export interface Options {
  name?: string;
}

/** A registering member the way a framework declares it: a property whose
 * type is one callable interface. The second parameter is options where a
 * claim puts the handler, so no declaration verifies against the claims and
 * a call reaches its op only through the instance the maker builds. */
export interface Matcher<H, R> {
  (path: string, options: Options, ...handlers: H[]): R;
}

/** The routing members a server package inherits from a base package. */
export interface Routing<H> {
  get: Matcher<H, this>;
  post: Matcher<H, this>;
}
